"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"550\" y=\"825\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"26\">WHY IT ENDURES</text><text x=\"550\" y=\"865\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">A ruler practicing what he preached</text><text x=\"550\" y=\"900\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">No hypocrisy — Marcus walked the talk under crushing pressure</text><rect x=\"200\" y=\"970\" width=\"700\" height=\"80\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"1020\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">\"You have power over your mind — not outside events.\"</text></svg>",
