"#f59e0b\" font-weight=\"bold\" font-size=\"22\">SENECA</text><text x=\"170\" y=\"638\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">4 BCE-65 CE — Statesman, tutor to Nero</text><text x=\"950\" y=\"638\" text-anchor=\"end\" fill=\"#888\" font-size=\"18\">Rome</text><rect x=\"100\" y=\"690\" width=\"900\" height=\"110\" rx=\"20\" fill=\"rgba(239,68,68,0.12)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"170\" y=\"735\" text-anchor=\"start\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"22\">MUSONIUS RUFUS</text><text x=\"170\" y=\"768\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">~30-100 CE — Taught Epictetus</text><text x=\"950\" y=\"768\" text-anchor=\"end\" fill=\"#888\" font-size=\"18\">Rome</text><rect x=\"100\" y=\"820\" width=\"900\" height=\"110\" rx=\"20\" fill=\"rgba(236,72,153,0.12)\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"170\" y=\"865\" text-anchor=\"start\" fill=\"#ec4899\" font-weight=\"bold\" font-size=\"22\">EPICTETUS</text><text x=\"170\" y=\"898\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">~50-135 CE — Former slave, wrote Discourses</text><text x=\"950\" y=\"898\" text-anchor=\"end\" fill=\"#888\" font-size=\"18\">Nicopolis</text><rect x=\"100\" y=\"950\" width=\"900\" height=\"110\" rx=\"20\" fill=\"rgba(255,215,0,0.15)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"170\" y=\"995\" text-anchor=\"start\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"22\">MARCUS AURELIUS</text><text x=\"170\" y=\"1028\" text-anchor=\"start\" fill=\"#fff\" font-size=\"20\">121-180 CE — Emperor & student of Epictetus</text><text x=\"950\" y=\"1028\" text-anchor=\"end\" fill=\"#888\" font-size=\"18\">Rome</text></svg>",
