      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">WISDOM</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">Closing the first lesson</text><rect x=\"100\" y=\"300\" width=\"900\" height=\"400\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"430\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"42\">\"What we do now</text><text x=\"550\" y=\"490\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"42\">echoes in eternity.\"</text><text x=\"900\" y=\"620\" text-anchor=\"end\" fill=\"#8b5cf6\" font-size=\"24\">— Marcus Aurelius</text><text x=\"900\" y=\"660\" text-anchor=\"end\" fill=\"#888\" font-size=\"20\">Meditations 4.42</text><rect x=\"200\" y=\"780\" width=\"700\" height=\"200\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"840\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">From a man writing to himself</text><text x=\"550\" y=\"880\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">in a war tent at the edge of empire</text><text x=\"550\" y=\"925\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">1,850 years ago.</text><text x=\"550\" y=\"960\" text-anchor=\"middle\" fill=\"#888\" font-size=\"20\">Still speaking. Still right.</text></svg>",
