      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">PREMEDITATIO MALORUM</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">The pre-meditation of evils</text><rect x=\"60\" y=\"180\" width=\"460\" height=\"280\" rx=\"20\" fill=\"rgba(239,68,68,0.12)\" stroke=\"#ef4444\" stroke-width=\"2\"/><text x=\"290\" y=\"235\" text-anchor=\"middle\" fill=\"#ef4444\" font-weight=\"bold\" font-size=\"24\">UNREHEARSED</text><text x=\"290\" y=\"285\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Misfortune strikes twice:</text><text x=\"290\" y=\"325\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">once as event</text><text x=\"290\" y=\"360\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">once as shock</text><text x=\"290\" y=\"415\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">The shock was optional</text><rect x=\"580\" y=\"180\" width=\"460\" height=\"280\" rx=\"20\" fill=\"rgba(16,185,129,0.12)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"810\" y=\"235\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"24\">REHEARSED</text><text x=\"810\" y=\"285\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Misfortune strikes once —</text><text x=\"810\" y=\"325\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">and finds you</text><text x=\"810\" y=\"360\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"20\">already positioned</text><text x=\"810\" y=\"415\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">Surprise removed in advance</text><rect x=\"150\" y=\"500\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"555\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"26\">CICERO, TUSC. DISP. 3.29</text><text x=\"550\" y=\"600\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">\"The foresight of future evils</text><text x=\"550\" y=\"638\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">softens their arrival.\"</text><rect x=\"150\" y=\"720\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"775\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"26\">ANAXAGORAS, ON HIS SON'S DEATH</text><text x=\"550\" y=\"820\" text-anchor=\"middle\" fill=\"#fff\" font-style=\"italic\" font-size=\"22\">\"I knew I had begotten a mortal.\"</text><text x=\"550\" y=\"858\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">The rehearsal had been running for years</text><rect x=\"200\" y=\"940\" width=\"700\" height=\"120\" rx=\"20\" fill=\"rgba(255,215,0,0.1)\" stroke=\"#ffd700\" stroke-width=\"2\"/><text x=\"550\" y=\"990\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"22\">Marcus's 2.1 morning list of difficult people</text><text x=\"550\" y=\"1030\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">is premeditatio applied to the day ahead</text></svg>",
