      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\"><rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"70\" text-anchor=\"middle\" fill=\"#ffd700\" font-weight=\"bold\" font-size=\"36\">KNOWLEDGE CHECK</text><text x=\"550\" y=\"115\" text-anchor=\"middle\" fill=\"#888\" font-size=\"24\">First in order vs first in purpose</text><rect x=\"150\" y=\"180\" width=\"800\" height=\"180\" rx=\"20\" fill=\"rgba(99,102,241,0.12)\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"232\" text-anchor=\"middle\" fill=\"#6366f1\" font-weight=\"bold\" font-size=\"24\">WISDOM: FIRST IN ORDER</text><text x=\"550\" y=\"277\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Sort correctly before acting correctly</text><text x=\"550\" y=\"315\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">The eyes of the system</text><rect x=\"150\" y=\"390\" width=\"800\" height=\"200\" rx=\"20\" fill=\"rgba(16,185,129,0.15)\" stroke=\"#10b981\" stroke-width=\"2\"/><text x=\"550\" y=\"442\" text-anchor=\"middle\" fill=\"#10b981\" font-weight=\"bold\" font-size=\"26\">JUSTICE: FIRST IN PURPOSE (11.10)</text><text x=\"550\" y=\"487\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Humans are social by nature —</text><text x=\"550\" y=\"525\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">the other virtues are instruments FOR this</text><text x=\"550\" y=\"562\" text-anchor=\"middle\" fill=\"#888\" font-size=\"18\">9.31: \"good character and acts for the common good\"</text><rect x=\"150\" y=\"620\" width=\"800\" height=\"170\" rx=\"20\" fill=\"rgba(245,158,11,0.12)\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"550\" y=\"672\" text-anchor=\"middle\" fill=\"#f59e0b\" font-weight=\"bold\" font-size=\"24\">THE OPERATIONAL TEST</text><text x=\"550\" y=\"715\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"21\">When justice conflicted with convenience,</text><text x=\"550\" y=\"750\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"21\">justice won — that's what top-ranked means</text><rect x=\"150\" y=\"820\" width=\"800\" height=\"240\" rx=\"20\" fill=\"rgba(139,92,246,0.12)\" stroke=\"#8b5cf6\" stroke-width=\"2\"/><text x=\"550\" y=\"875\" text-anchor=\"middle\" fill=\"#8b5cf6\" font-weight=\"bold\" font-size=\"24\">THE ARCHITECTURE</text><text x=\"550\" y=\"925\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Wisdom = the eyes</text><text x=\"550\" y=\"965\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Courage + Temperance = the hands</text><text x=\"550\" y=\"1005\" text-anchor=\"middle\" fill=\"#fff\" font-size=\"22\">Justice = what the hands are building</text><text x=\"550\" y=\"1042\" text-anchor=\"middle\" fill=\"#888\" font-size=\"17\">Instruments, and what they're for</text></svg>",
